CREATE TABLE `{{.schema}}`.`column_mappings_test` (
    _order INT,
    _tinyint TINYINT,
    _smallint SMALLINT,
    _int INT,
    _bigint BIGINT,
    _float FLOAT,
    _double DOUBLE,
    _decimal DECIMAL(10,2),
    _string STRING,
    _varchar VARCHAR(10),
    _char CHAR(3),
    _boolean BOOLEAN,
    _date DATE,
    _datetime DATETIME,
    _timestamp TIMESTAMP,
    _timestamp_ntz TIMESTAMP_NTZ,
    _binary BINARY,
    _json JSON,
    _array ARRAY<INT>,
    _map MAP<STRING,INT>,
    _struct STRUCT<a:INT, b:STRING>
) LIFECYCLE 1;

